INSERT INTO electricity_tips (title, message, category, icon, difficulty, savings_level, dorm_relevance) VALUES
('Turn Off the RGB Lights', 'RGB on keyboards and PC case fans look cool, but leaving them on 24/7 wastes electricity. Turn them off when studying or sleeping.', 'Gaming & Entertainment', 'game-controller-outline', 'Easy', 'Low', 'Student'),
('Cap Your Frame Rate (FPS)', 'If you are playing casual games, cap your FPS to your monitors refresh rate (e.g., 60Hz or 144Hz). Uncapped FPS forces your GPU to draw maximum wattage and generate massive heat.', 'Gaming & Entertainment', 'game-controller-outline', 'Medium', 'Moderate', 'Student'),
('Stop Using Screens for Background Noise', 'Many students leave YouTube running on a second monitor or TV just for background noise while studying. Use a low-power Bluetooth speaker or phone earphones instead.', 'Gaming & Entertainment', 'game-controller-outline', 'Easy', 'Moderate', 'Apartment'),
('Undervolt Your Gaming Laptop', 'Gaming laptops draw huge power and overheat easily in small dorm rooms. Undervolting your CPU slightly reduces power consumption and heat without affecting performance.', 'Gaming & Entertainment', 'game-controller-outline', 'Hard', 'High', 'Student'),
('Unplug the Console During Weekdays', 'Consoles like the PS5 or Xbox consume phantom power in Rest Mode to download updates. If you only play on weekends, unplug it completely during the week.', 'Gaming & Entertainment', 'game-controller-outline', 'Easy', 'Low', 'Boarding House');
